module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

reg [2:0] state;
reg [3:0] counter;

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
        state <= 3'd0;
        counter <= 4'd0;
    end else begin
        if (state == 3'd0) begin // RED
            if (counter == 3'd2) begin
                state <= 3'd1;
                counter <= 4'd0;
            end else begin
                counter <= counter + 1;
            end
        end else if (state == 3'd1) begin // GREEN
            if (counter == 4'd3) begin
                state <= 3'd2;
                counter <= 4'd0;
            end else begin
                counter <= counter + 1;
            end
        end else if (state == 3'd2) begin // YELLOW
            if (counter == 4'd1) begin
                state <= 3'd0;
                counter <= 4'd0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        case (state)
            3'd0: begin
                light <= 2'b00;
                walk <= 1'b1;
            end
            3'd1: begin
                light <= 2'b01;
                walk <= 1'b0;
            end
            3'd2: begin
                light <= 2'b10;
                walk <= 1'b0;
            end
        endcase
    end
end

always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
    end else begin
        if (state == 3'd1 && ped) begin
            state <= 3'd2;
            counter <= 4'd0;
        end
    end
end

endmodule

